//--------------------------------------------------------------------------//
//! \desc  Init. the vars used for atomic sections
//!        

//! \assume -none- 

//! \notes  Private function.Called by create function.

//! \param  reg       the Reg_Table object
//! \param  atomic    the type of atomic section

//! \return -none-

//--------------------------------------------------------------------------//


void reg_atomic_init( Reg_Table reg , Reg_Atomic atomic )
{
    reg->atomic_vars.atomic = atomic ; 

    if( !!(reg->atomic_vars.atomic & REG_ATOMIC_USE_RES) ) 
    {
        reg->atomic_vars.res = os_res_create() ;     
    }          

    reg->atomic_vars.fiq_state      = 0 ; 
    reg->atomic_vars.irq_state      = 0 ;
    reg->atomic_vars.irq_num_grants = 0 ; 
    reg->atomic_vars.fiq_num_grants = 0 ; 

}

